import React, { useState, useEffect } from 'react';
import './Filter.css';
import ProductCard from './ProductCard';
import ReactSlider from 'react-slider';
import axios from 'axios';
import PlaceholderCard from './Placeholder';
import Header from '../Components/Header';
import Footer from './Footer';

function JewelleryFilter() {
  const [openSection, setOpenSection] = useState([]);
  const [minValue, setMinValue] = useState(0);
  const [maxValue, setMaxValue] = useState(60000);
  const [jewellery, setJewellery] = useState([]);
  const [filteredJewellery, setFilteredJewellery] = useState([]);
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 8;

  // Filter states
  const [selectedColours, setSelectedColours] = useState([]);
  const [selectedOccasions, setSelectedOccasions] = useState([]);
  const [selectedOrigins, setSelectedOrigins] = useState([]);
  const [selectedCrafts, setSelectedCrafts] = useState([]);

  useEffect(() => {
    axios.get('http://localhost:3000/api/Jewellry')
      .then(response => {
        setJewellery(response.data);
        setFilteredJewellery(response.data);
      })
      .catch(error => {
        console.error("Error fetching Jewellery data:", error);
      });
  }, []);

  useEffect(() => {
    applyFilters();
  }, [minValue, maxValue, selectedColours, selectedOccasions, selectedOrigins, selectedCrafts]);

  const applyFilters = () => {
    const filtered = jewellery.filter(jewellery => {
      const meetsPrice = jewellery.price >= minValue && jewellery.price <= maxValue;
      const meetsColour = selectedColours.length === 0 || selectedColours.includes(jewellery.color);
      const meetsOccasion = selectedOccasions.length === 0 || selectedOccasions.includes(jewellery.occasion);
      const meetsOrigin = selectedOrigins.length === 0 || selectedOrigins.includes(jewellery.origin);
      const meetsCraft = selectedCrafts.length === 0 || selectedCrafts.includes(jewellery.craft);

      return meetsPrice && meetsColour && meetsOccasion && meetsOrigin && meetsCraft;
    });

    setFilteredJewellery(filtered);
    setCurrentPage(1);
  };

  const resetFilters = () => {
    setMinValue(0);
    setMaxValue(60000);
    setSelectedColours([]);
    setSelectedOccasions([]);
    setSelectedOrigins([]);
    setSelectedCrafts([]);
    setFilteredJewellery(jewellery);
    setCurrentPage(1);
  };

  const toggleContent = (section) => {
    setOpenSection(prev => 
      prev.includes(section) ? prev.filter(item => item !== section) : [...prev, section]
    );
  };

  const handleSliderChange = ([min, max]) => {
    setMinValue(min);
    setMaxValue(max);
  };

  const handleCheckboxChange = (setFilterState, value) => {
    setFilterState(prevState =>
      prevState.includes(value) ? prevState.filter(item => item !== value) : [...prevState, value]
    );
  };

  const lastIndex = currentPage * itemsPerPage;
  const firstIndex = lastIndex - itemsPerPage;
  const currentJewellery = filteredJewellery.slice(firstIndex, lastIndex);

  const nextPage = () => {
    if (currentPage < Math.ceil(filteredJewellery.length / itemsPerPage)) {
      setCurrentPage(currentPage + 1);
    }
  };

  const prevPage = () => {
    if (currentPage > 1) {
      setCurrentPage(currentPage - 1);
    }
  };

  const placeholdersNeeded = itemsPerPage - currentJewellery.length;

  return (
    <div>
    <div className="filter-page">
      <Header/>
      <div className="filter-section">
        <h2>Filter By</h2>        
        <div className="filter-options">
          {/* Price Filter */}
          <div className="price-slider filter-category" onClick={() => toggleContent('price')}>
            <p>Price</p>
            <i className="arrow">{openSection.includes('price') ? '▲' : '▼'}</i>
          </div>
          {openSection.includes('price') && (
            <div className="filter-content">
              <input type="number" value={minValue} onChange={(e) => setMinValue(Number(e.target.value))} className="price-input" />
              <input type="number" value={maxValue} onChange={(e) => setMaxValue(Number(e.target.value))} className="price-input" />
              <ReactSlider
                className="slider"
                thumbClassName="thumb"
                trackClassName="track"
                min={1}
                max={60000}
                value={[minValue, maxValue]}
                onChange={handleSliderChange}
                pearling
                minDistance={0}
              />
            </div>
          )}

          {/* Fabric Filter
          <div className="filter-category" onClick={() => toggleContent('fabric')}>
            <p>Fabric</p>
            <i className="arrow">{openSection.includes('fabric') ? '▲' : '▼'}</i>
          </div>
          {openSection.includes('fabric') && (
            <div className="filter-content">
              {['Cotton', 'Silk', 'Linen'].map(fabric => (
                <label key={fabric}>
                  <input type="checkbox" 
                         checked={selectedFabrics.includes(fabric)}
                         onChange={() => handleCheckboxChange(setSelectedFabrics, fabric)} />
                  {fabric}
                </label>
              ))}
            </div>
          )} */}

          {/* Colour Filter */}
          <div className="filter-category" onClick={() => toggleContent('colour')}>
            <p>Colour</p>
            <i className="arrow">{openSection.includes('colour') ? '▲' : '▼'}</i>
          </div>
          {openSection.includes('colour') && (
            <div className="filter-content">
              {['Gold', 'Silver', 'Oxidised', 'Platinum', 'Diamond', 'Rose Gold'].map(color => (
                <label key={color}>
                  <input type="checkbox" 
                         checked={selectedColours.includes(color)}
                         onChange={() => handleCheckboxChange(setSelectedColours, color)} />
                  {color}
                </label>
              ))}
            </div>
          )}

          {/* Occasion Filter */}
          <div className="filter-category" onClick={() => toggleContent('occasion')}>
            <p>Occasion</p>
            <i className="arrow">{openSection.includes('occasion') ? '▲' : '▼'}</i>
          </div>
          {openSection.includes('occasion') && (
            <div className="filter-content">
              {['Wedding', 'Special Occasions', 'Casual'].map(occasion => (
                <label key={occasion}>
                  <input type="checkbox" 
                         checked={selectedOccasions.includes(occasion)}
                         onChange={() => handleCheckboxChange(setSelectedOccasions, occasion)} />
                  {occasion}
                </label>
              ))}
            </div>
          )}

          {/* Origin Filter */}
          <div className="filter-category" onClick={() => toggleContent('origin')}>
            <p>Origin</p>
            <i className="arrow">{openSection.includes('origin') ? '▲' : '▼'}</i>
          </div>
          {openSection.includes('origin') && (
            <div className="filter-content">
              {['Pride', 'Ratna', 'Apurva'].map(origin => (
                <label key={origin}>
                  <input type="checkbox" 
                         checked={selectedOrigins.includes(origin)}
                         onChange={() => handleCheckboxChange(setSelectedOrigins, origin)} />
                  {origin}
                </label>
              ))}
            </div>
          )}

          {/* Craft Filter */}
          <div className="filter-category" onClick={() => toggleContent('craft')}>
            <p>Craft</p>
            <i className="arrow">{openSection.includes('craft') ? '▲' : '▼'}</i>
          </div>
          {openSection.includes('craft') && (
            <div className="filter-content">
              {['Woven', 'Sanganeri', 'Block Print'].map(craft => (
                <label key={craft}>
                  <input type="checkbox" 
                         checked={selectedCrafts.includes(craft)}
                         onChange={() => handleCheckboxChange(setSelectedCrafts, craft)} />
                  {craft}
                </label>
              ))}
            </div>
          )}
        </div>
        <div className="reset-button-container">
          <button className="reset-button" onClick={resetFilters}>Reset Filters</button>
        </div>
      </div>

      <div className="search-section">
        <div className="product-list">
          {currentJewellery.map((jewellery, index) => (
            <ProductCard key={index} jewellery={jewellery} />
          ))}
          {placeholdersNeeded > 0 && Array(placeholdersNeeded).fill(<PlaceholderCard />)}
        </div>

        <div className="pagination">
          <button onClick={prevPage} disabled={currentPage === 1}>Previous</button>
          <button onClick={nextPage} disabled={currentPage === Math.ceil(filteredJewellery.length / itemsPerPage)}>Next</button>
        </div>
      </div>
    </div>
    <Footer/>
    </div>
  );
}

export default JewelleryFilter;
